        "abstract": "傳回在特定次數的二項分配實驗中，實驗成功的機率。 若實驗的結果不是成功就是失敗，並且任何實驗都是獨立的，同時在整個實驗中，成功的機率是常數，便可使用 BINOMDIST 函數來解決固定實驗次數的問題。 例如，BINOMDIST 可以計算下三胎中有兩男的機率。",
