        "description": "傳回負二項分配。 當成功常數機率為 probability_s 時，NEGBINOMDIST 會傳回 number_s 成功之前有 number_f 次失敗的機率。 此函數類似於二項分配，不過成功次數是固定的，而試驗的次數是變動的。 如同二項分配，也會假定每次試驗都是獨立的。",
